def transform_v2(grid):
    """
    Cell transformations:
    - Background (bg) becomes 3 if:
      * bg has special AFTER in row AND special AFTER in col, OR
      * bg has special AFTER in row AND special BEFORE in col, OR
      * bg has special BEFORE in row AND special AFTER in col
    - Background becomes 2 if has special AFTER in row AND special BEFORE in col
    - Special (2) becomes 3 if strictly between two specials in row OR column
    """
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    bg = grid[0][0]

    # Collect all special cells at start
    original_specs = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                original_specs.add((r, c))

    # First pass: mark specials that become 3 (strictly between)
    # Process in reverse order so we don't accidentally use newly marked cells
    for r in range(h):
        specs = sorted([c for c in range(w) if grid[r][c] != bg])
        for i in range(len(specs) - 1):
            for c in range(specs[i] + 1, specs[i+1]):
                if grid[r][c] == bg:
                    result[r][c] = 3

    for c in range(w):
        specs = sorted([r for r in range(h) if grid[r][c] != bg])
        for i in range(len(specs) - 1):
            for r in range(specs[i] + 1, specs[i+1]):
                if grid[r][c] == bg:
                    result[r][c] = 3

    # Second pass: background becomes 2 if has special AFTER in row AND BEFORE in col
    # Columns with specials BEFORE this row
    col_has_special_before = []
    for c in range(w):
        specs = sorted([r for r in range(h) if grid[r][c] != bg])
        col_has_special_before.append(specs)

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg:
                # Has special after in row?
                row_specs = sorted([cc for cc in range(w) if grid[r][cc] != bg])
                if not row_specs:
                    continue
                has_after = any(cc > c for cc in row_specs)

                # Has special before in col?
                col_specs = col_has_special_before[c]
                has_before = any(rr < r for rr in col_specs) if col_specs else False

                if has_after and has_before:
                    result[r][c] = 2

    return result

